DATA = "diff --git a/skills/codex-delegate/scripts/relay.mjs b/skills/codex-delegate/scripts/relay.mjs\nindex 70372f8..38a6a66 100644\n--- a/skills/codex-delegate/scripts/relay.mjs\n+++ b/skills/codex-delegate/scripts/relay.mjs\n@@ -164,12 +164,8 @@ function timestamp() {\n function buildArgv(opts, finalPath) {\n   const argv = [\"exec\"];\n   if (opts.resumeLast) argv.push(\"resume\", \"--last\");\n-  // ponytail: shell:true on win32 (needed for the codex.cmd shim) doesn't quote\n-  // args, so a temp path with spaces (C:\\Users\\First Last\\...) splits and the\n-  // trailing \"-\" misparses (issue #3). Quote the only spaceable arg in argv.\n-  // Ceiling: if quoting proves too blunt, drop shell:true and resolve the shim.\n-  const outPath = process.platform === \"win32\" ? `\"${finalPath}\"` : finalPath;\n-  argv.push(\"--json\", \"-o\", outPath);\n+  // Pass a raw path here; platform-specific quoting belongs at process launch.\n+  argv.push(\"--json\", \"-o\", finalPath);\n   // `-s`/`-C` are not accepted by `exec resume`; resume inherits the original\n   // session's sandbox and working root, and we set the child process cwd below.\n   if (!opts.resumeLast) {\n@@ -181,6 +177,30 @@ function buildArgv(opts, finalPath) {\n   return argv;\n }\n \n+// cmd.exe is required for npm's Windows codex.cmd shim. Keep every CLI\n+// argument inside one quoted cmd token, and reject values that cmd can expand\n+// even inside quotes. In particular, %VAR% and !VAR! are not inert strings.\n+function quoteForCmd(value) {\n+  const arg = String(value);\n+  if (/[\"%!\\r\\n]/u.test(arg)) {\n+    throw new Error(\"Windows cmd cannot safely pass an argument containing quotes, percent signs, exclamation marks or newlines\");\n+  }\n+  return `\"${arg}\"`;\n+}\n+\n+function spawnCodex(argv, opts) {\n+  const common = { cwd: opts.cd, stdio: [\"pipe\", \"pipe\", \"pipe\"] };\n+  if (process.platform !== \"win32\") return spawn(\"codex\", argv, common);\n+\n+  // cmd /s removes the outer pair of quotes; the inner pairs preserve argv\n+  // boundaries, including the trailing stdin sentinel and space-bearing paths.\n+  const commandLine = `\"${[\"codex\", ...argv].map(quoteForCmd).join(\" \")}\"`;\n+  return spawn(\"cmd.exe\", [\"/d\", \"/v:off\", \"/s\", \"/c\", commandLine], {\n+    ...common,\n+    windowsHide: true,\n+  });\n+}\n+\n function extractThreadId(event) {\n   return (\n     event.thread_id ??\n@@ -253,10 +273,14 @@ function reportUnavailable(writeResult, resultPath) {\n \n function dispatchToCodex(opts, brief, run, writeResult) {\n   const argv = buildArgv(opts, run.finalPath);\n-  // shell:true on Windows so the codex.cmd shim resolves (see codexVersion). Safe:\n-  // the brief is fed via child.stdin below — never argv — and argv holds only\n-  // sandbox enums, model names, and file paths, with no shell metacharacters.\n-  const child = spawn(\"codex\", argv, { cwd: opts.cd, stdio: [\"pipe\", \"pipe\", \"pipe\"], shell: process.platform === \"win32\" });\n+  let child;\n+  try {\n+    child = spawnCodex(argv, opts);\n+  } catch (err) {\n+    const result = writeResult({ status: \"failed\", exitCode: 1, signal: null, threadId: null, finalMessage: \"\", touchedFiles: gitTouchedFiles(opts.cd), error: String(err && err.message ? err.message : err) });\n+    printSummary(result, run.resultPath);\n+    process.exit(1);\n+  }\n \n   let threadId = null;\n   let stdoutBuf = \"\";\n"
